import re
import sys
from collections import defaultdict
from datetime import datetime

LOG_PATTERN = re.compile(
    r'(\S+)\s+\S+\s+\S+\s+\[([^\]]+)\]\s+"([^"]*)"\s+(\d+)\s+(\S+)'
)

def parse_log_line(line):
    match = LOG_PATTERN.match(line.strip())
    if not match:
        return None
    timestamp_str = match.group(2)
    try:
        dt = datetime.strptime(timestamp_str.split()[0], '%d/%b/%Y:%H:%M:%S')
        return dt.hour
    except ValueError:
        return None

def aggregate_hourly_counts(log_lines):
    counts = defaultdict(int)
    for line in log_lines:
        hour = parse_log_line(line)
        if hour is not None:
            counts[hour] += 1
    return dict(counts)

def main():
    print('Hourly counts computed')

    sample_logs = [
        '127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 2326',
        '127.0.0.1 - frank [10/Oct/2000:14:25:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 2326',
        '127.0.0.1 - frank [10/Oct/2000:13:45:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 2326',
        '127.0.0.1 - frank [10/Oct/2000:15:05:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 2326',
        '127.0.0.1 - frank [10/Oct/2000:13:15:36 -0700] "GET /apache_pb.gif HTTP/1.0" 200 2326',
        '127.0.0.1 - frank [10/Oct/2000:00:30:00 -0700] "GET /index.html HTTP/1.0" 200 1234',
        '127.0.0.1 - frank [10/Oct/2000:23:59:59 -0700] "GET /about.html HTTP/1.0" 404 567',
    ]

    if not sys.stdin.isatty():
        log_lines = sys.stdin.readlines()
        if not log_lines:
            log_lines = sample_logs
    else:
        log_lines = sample_logs

    counts = aggregate_hourly_counts(log_lines)

    for hour in sorted(counts):
        print(f"Hour {hour:02d}: {counts[hour]}")

if __name__ == '__main__':
    main()

from qiskit import QuantumCircuit, transpile

def get_simulator():
    try:
        from qiskit_aer import AerSimulator
        return AerSimulator()
    except ImportError:
        pass
    try:
        from qiskit.providers.aer import AerSimulator
        return AerSimulator()
    except ImportError:
        pass
    try:
        from qiskit.providers.basic_provider import BasicSimulator
        return BasicSimulator()
    except ImportError:
        raise ImportError("No suitable simulator found. Please install qiskit-aer or use Qiskit 1.0+.")

def main():
    qc = QuantumCircuit(2, 2)

    # Prepare shared Bell pair
    qc.h(0)
    qc.cx(0, 1)

    # Alice encodes message '11'
    qc.x(0)
    qc.z(0)

    # Bob decodes
    qc.cx(0, 1)
    qc.h(0)

    # Measure both qubits
    qc.measure(0, 0)
    qc.measure(1, 1)

    simulator = get_simulator()
    transpiled = transpile(qc, simulator)
    job = simulator.run(transpiled, shots=1024)
    result = job.result()
    counts = result.get_counts()

    received = max(counts, key=counts.get)
    print(f"Received: {received}")

if __name__ == "__main__":
    main()

import re

def parse_apache_log(line):
    """Parse an Apache combined log format line and return the HTTP status code."""
    match = re.search(r'" \d{3} ', line)
    if match:
        status_str = match.group().strip('" ')
        return int(status_str)
    return None

def count_status_groups(lines):
    """Count status codes by group (2xx, 4xx, 5xx)."""
    counts = {'2xx': 0, '4xx': 0, '5xx': 0}
    for line in lines:
        status = parse_apache_log(line)
        if status is not None:
            if 200 <= status < 300:
                counts['2xx'] += 1
            elif 400 <= status < 500:
                counts['4xx'] += 1
            elif 500 <= status < 600:
                counts['5xx'] += 1
    return counts

